package com.example.dsatracker.controller;import com.example.dsatracker.dto.ProblemRequestDTO;import com.example.dsatracker.dto.ProblemResponseDTO;import com.example.dsatracker.service.ProblemService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/problems")public class ProblemController {    private final ProblemService service;    public ProblemController(ProblemService service) {        this.service = service;    }    @PostMapping    public ResponseEntity<ProblemResponseDTO> createProblem(            @Valid @RequestBody ProblemRequestDTO request) {        ProblemResponseDTO response = service.createProblem(request);        return ResponseEntity                .status(HttpStatus.CREATED)                .body(response);    }}